"""Котик на рабочем столе (Windows) с иконкой в трее.

Что умеет:
  - ходит по экрану (иногда останавливается)
  - левая кнопка мыши по коту: взять и перетащить (если отпустить в воздухе, он упадёт)
  - правая кнопка мыши по коту: быстрое меню
  - иконка в трее: щелчок включает/выключает котика, правая кнопка - полное меню:
    размер, экран, зона прогулок, положение (поверх окон / под окнами),
    запуск вместе с Windows, выход. Все настройки запоминаются.
"""
import base64
import io
import json
import math
import os
import queue
import random
import shutil
import sys
import tkinter as tk
from collections import OrderedDict

try:
    import pystray
    from PIL import Image
except ImportError:          # без трея программа всё равно работает
    pystray = None

def start_media_watch(on_change, is_enabled):
    """Следит за тем, что играет в Windows (Spotify, Медиаплеер, браузер, AIMP и т.д.).
    Когда меняется песня и музыка играет - вызывает on_change(). Нужен пакет winrt;
    если его нет, функция просто возвращает False, а котик работает как обычно."""
    try:
        try:
            from winrt.windows.media.control import GlobalSystemMediaTransportControlsSessionManager as Manager
        except ImportError:
            from winsdk.windows.media.control import GlobalSystemMediaTransportControlsSessionManager as Manager
    except Exception:
        return False
    import asyncio
    import threading

    PLAYING = 4

    async def read(mgr):
        session = mgr.get_current_session()
        if session is None:
            return None, 0
        info = session.get_playback_info()
        status = int(info.playback_status) if info is not None else 0
        props = await session.try_get_media_properties_async()
        title = (props.title or "") if props is not None else ""
        artist = (props.artist or "") if props is not None else ""
        return (session.source_app_user_model_id, title, artist), status

    async def run():
        mgr = await Manager.request_async()
        last, pending = None, False
        while True:
            try:
                key, status = await read(mgr)
            except Exception:
                key, status = None, 0
            if key is not None and key[1]:
                if last is None:
                    last = key                      # то, что играло при запуске, не считается
                elif key != last:
                    last, pending = key, True
                if pending and status == PLAYING:
                    pending = False
                    if is_enabled():
                        on_change()
            await asyncio.sleep(2)

    def worker():
        try:
            asyncio.run(run())
        except Exception:
            pass

    threading.Thread(target=worker, daemon=True).start()
    return True


KEY = "#fe00fe"      # этот цвет станет прозрачным
TICK = 50            # миллисекунд на один «тик»
