CONFIG_DIR = os.path.join(os.environ.get("APPDATA") or os.path.expanduser("~"), "CatPet")
CONFIG_FILE = os.path.join(CONFIG_DIR, "settings.json")
_mutex = None


def load_config():
    try:
        with open(CONFIG_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def save_config(cfg):
    try:
        os.makedirs(CONFIG_DIR, exist_ok=True)
        with open(CONFIG_FILE, "w", encoding="utf-8") as f:
            json.dump(cfg, f)
    except Exception:
        pass


# ---------- Windows: экраны, слои, автозапуск ----------
def enable_dpi_awareness():
    """Чтобы картинка не размывалась на экранах с масштабом 125-200 %."""
    try:
        import ctypes
        try:
            ctypes.windll.shcore.SetProcessDpiAwareness(1)
        except Exception:
            ctypes.windll.user32.SetProcessDPIAware()
    except Exception:
        pass


def already_running():
    """Не даём запустить вторую копию (например, вручную и из автозапуска)."""
    global _mutex
    try:
        import ctypes
        _mutex = ctypes.windll.kernel32.CreateMutexW(None, False, "CatPet_single_instance")
        return ctypes.windll.kernel32.GetLastError() == 183
    except Exception:
        return False


def get_monitors():
    """Список экранов: {'rect': (x0,y0,x1,y1), 'work': (...без панели задач...), 'primary': bool}."""
    mons = []
    try:
        import ctypes
        from ctypes import wintypes

        class MONITORINFO(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.DWORD), ("rcMonitor", wintypes.RECT),
                        ("rcWork", wintypes.RECT), ("dwFlags", wintypes.DWORD)]

        user32 = ctypes.windll.user32
        user32.GetMonitorInfoW.argtypes = [ctypes.c_void_p, ctypes.POINTER(MONITORINFO)]
        proc_type = ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p,
                                       ctypes.POINTER(wintypes.RECT), ctypes.c_void_p)

        def callback(hmon, hdc, rect, data):
            info = MONITORINFO()
            info.cbSize = ctypes.sizeof(MONITORINFO)
            if user32.GetMonitorInfoW(hmon, ctypes.byref(info)):
                r, w = info.rcMonitor, info.rcWork
                mons.append({"rect": (r.left, r.top, r.right, r.bottom),
                             "work": (w.left, w.top, w.right, w.bottom),
                             "primary": bool(info.dwFlags & 1)})
            return 1

        user32.EnumDisplayMonitors(None, None, proc_type(callback), 0)
    except Exception:
        mons = []
    mons.sort(key=lambda m: (not m["primary"], m["rect"][0], m["rect"][1]))
    return mons


def push_to_bottom(root):
    """Опустить окно котика под все остальные окна (но над рабочим столом)."""
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        user32.GetParent.argtypes = [wintypes.HWND]
        user32.GetParent.restype = wintypes.HWND
        user32.SetWindowPos.argtypes = [wintypes.HWND, wintypes.HWND, ctypes.c_int, ctypes.c_int,
                                        ctypes.c_int, ctypes.c_int, wintypes.UINT]
        hwnd = user32.GetParent(root.winfo_id()) or root.winfo_id()
        # HWND_BOTTOM = 1; SWP_NOSIZE | SWP_NOMOVE | SWP_NOACTIVATE
        user32.SetWindowPos(hwnd, wintypes.HWND(1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010)
    except Exception:
        root.lower()


# Автозапуск - обычный ярлык в папке «Автозагрузка» (как у Telegram, Discord и т.п.), без записи в реестр.
# Установщик кладёт готовый ярлык-образец в папку программы; меню трея просто копирует его туда или удаляет.
SHORTCUT = "CatPet.lnk"


def startup_dir():
    appdata = os.environ.get("APPDATA")
    return os.path.join(appdata, "Microsoft", "Windows", "Start Menu", "Programs", "Startup") if appdata else None


def shortcut_template():
    base = os.path.dirname(sys.executable if getattr(sys, "frozen", False) else os.path.abspath(__file__))
    p = os.path.join(base, "autostart", SHORTCUT)
    return p if os.path.exists(p) else None


def autostart_available():
    return startup_dir() is not None and shortcut_template() is not None


def autostart_enabled():
    d = startup_dir()
    return bool(d) and os.path.exists(os.path.join(d, SHORTCUT))


def set_autostart(on):
    d, tpl = startup_dir(), shortcut_template()
    if not d:
        return
    dst = os.path.join(d, SHORTCUT)
    try:
        if on and tpl:
            os.makedirs(d, exist_ok=True)
            shutil.copyfile(tpl, dst)
        elif not on and os.path.exists(dst):
            os.remove(dst)
    except OSError:
        pass


class Cat:
    """Мозг кошки: решает, что делать, и считает положение. От окна не зависит.

    Каждое действие - это «генератор» шагов (кадр, высота_прыжка, вперёд, вниз, сколько_тиков).
    Так можно держать важные кадры дольше (верх прыжка, присед перед прыжком) -
    это и есть тайминг в пиксельной анимации.
    """

    NEUTRAL = ("stand", "blink", "walk2")

    def __init__(self, w, h, screen, work_bottom, scale=3, mode="bottom", rect=None):
        self.W, self.H = w, h
        self.scale = scale
        self.screen = tuple(screen)               # (x0, y0, x1, y1) выбранного экрана
        self.work_bottom = work_bottom            # низ рабочей области (над панелью задач)
        self.custom_rect = None
        if rect and len(rect) == 4:
            x0, y0, x1, y1 = [int(v) for v in rect]
            self.custom_rect = (min(x0, x1), min(y0, y1), max(x0, x1), max(y0, y1))
        self.set_zone(mode)
        self.cx, self.fy = self.random_point()
        self.dz = 0                       # на сколько пикселей кот сейчас в воздухе
        self.facing = random.choice([-1, 1])
        self.frame = "stand"
        self.hold = 0
        self.gen = self.idle()
        self.dragging = False
        self.interrupt = False            # пришла команда «послушать музыку»
        self.in_music = False             # котик сейчас идёт слушать / слушает музыку
        self.walked = 0                   # сколько тиков котик прошагал и просидел - чтобы делить время 50/50
        self.seated = 0

    def request(self, name):
        """Команда извне (меню, смена песни). Только простые флаги - выполняется в удобный момент."""
        if name == "music" and not self.in_music and not self.dragging:
            self.interrupt = True

    @property
    def step(self):
        return BASE_STEP * self.scale

    # ---------- экран, размер, зона прогулок ----------
    def custom_ok(self):
        """Своя зона годится, если её центр лежит на выбранном экране."""
        if not self.custom_rect:
            return False
        x0, y0, x1, y1 = self.custom_rect
        sx0, sy0, sx1, sy1 = self.screen
        return sx0 <= (x0 + x1) / 2 <= sx1 and sy0 <= (y0 + y1) / 2 <= sy1

    def set_zone(self, mode, rect=None):
        if rect:
            x0, y0, x1, y1 = [int(v) for v in rect]
            self.custom_rect = (min(x0, x1), min(y0, y1), max(x0, x1), max(y0, y1))
        sx0, sy0, sx1, sy1 = self.screen
        floor = self.work_bottom
        if mode == "custom" and self.custom_ok():
            self.zone = self.custom_rect
        elif mode == "screen":
            self.zone = (sx0, min(sy0 + self.H, floor), sx1, floor)
        else:
            mode = "bottom"
            self.zone = (sx0, floor, sx1, floor)
        self.mode = mode

    def set_screen(self, screen, work_bottom):
        """Перевести котика на другой экран (по меню): зона по умолчанию - по низу."""
        self.screen, self.work_bottom = tuple(screen), work_bottom
        self.set_zone("bottom")
        self.cx, self.fy = self.random_point()
        self.dz, self.dragging = 0, False
        self.start(self.idle())

    def move_to_screen(self, screen, work_bottom):
        """Котика перенесли мышкой на другой экран: меняем экран и зону (по низу), позицию не трогаем."""
        self.screen, self.work_bottom = tuple(screen), work_bottom
        self.set_zone("bottom")

    def set_scale(self, scale, w, h):
        self.scale, self.W, self.H = scale, w, h
        self.set_zone(self.mode)
        self.cx, self.fy = self.clamp(self.cx, self.fy)

    def clamp(self, cx, fy):
        x0, y0, x1, y1 = self.zone
        cx = min(max(cx, x0), x1)
        fy = min(max(fy, y0), y1)
        half = self.W // 2
        sx0, sy0, sx1, sy1 = self.screen
        cx = min(max(cx, sx0 + half), sx1 - half)
        return int(cx), int(fy)

    def in_zone(self, cx, fy):
        tx, ty = self.clamp(cx, fy)
        return abs(tx - cx) <= 2 and abs(ty - fy) <= 2

    def random_point(self):
        x0, y0, x1, y1 = self.zone
        return self.clamp(random.uniform(x0, x1), random.uniform(y0, y1))

    def reposition(self):
        """Вернуть котика в зону (он идёт туда сам)."""
        self.start(self.after_drop())

    # ---------- действия ----------
    def idle(self):
        for _ in range(random.randint(6, 20)):
            if random.random() < 0.12:
                yield ("blink", 0, 0, 0, 2)
            else:
                yield ("stand", 0, 0, 0, 2)

    # ---------- позы ----------
    def pose(self):
        return POSE.get(self.frame, "stand")

    def is_sitting(self):
        return self.pose() != "stand"

    def start(self, gen):
        """Запустить действие. Если кот сидел - сначала плавно встаёт."""
        self.gen = self.chain(self.get_up(), gen) if self.is_sitting() else gen
        self.hold = 0

    @staticmethod
    def chain(first, second):
        yield from first
        yield from second

    def play(self, name):
        """Проиграть готовую анимацию из таблицы ANIMS."""
        for frame, ticks in ANIMS[name]:
            yield (frame, 0, 0, 0, ticks)

    def hold_frame(self, name, ticks):
        yield (name, 0, 0, 0, ticks)

    # ---------- ходьба ----------
    GLANCE_CHANCE = 0.5        # в прогулке кошка оглядывается назад

    def walk_to(self, tx, ty, glance=False):
        dx, dy = tx - self.cx, ty - self.fy
        dist = math.hypot(dx, dy)
        px = self.scale
        if dist < 2 * px:
            self.cx, self.fy = tx, ty
            return
        if self.frame not in self.NEUTRAL:
            yield ("stand", 0, 0, 0, 1)
        if abs(dx) > 6:
            self.facing = 1 if dx > 0 else -1               # смена стороны - мгновенная
        # число кадров кратно 8: кошка начинает с walk3 и заканчивает нейтральной позой walk2
        n = max(8, int(round(dist / (self.step * 0.9) / 8.0)) * 8)
        head = ["f"] * n                                    # f - смотрит вперёд, b - назад, t0..t2 - поворот
        if glance and n >= 28:
            back = random.randint(10, 20)                   # 1-2 секунды смотрит назад
            back = min(back, n - 14)
            s = random.randint(3, n - back - 9)
            seq = ["t2", "t1", "t0"] + ["b"] * back + ["t0", "t1", "t2"]
            head[s:s + len(seq)] = seq
        prof = [min(1.0, 0.35 + 0.65 * min(i + 1, n - i) / 3.0) for i in range(n)]   # разгон и торможение
        total, cum = sum(prof), 0.0
        x0, y0 = self.cx, self.fy
        for i in range(n):
            cum += prof[i]
            t = cum / total
            nx = x0 + int(round(dx * t / px)) * px            # по горизонтали шагаем кратно размеру пикселя
            ny = y0 + int(round(dy * t))
            k = (3 + i) % 8
            h = head[i]
            name = "walk%d" % k if h == "f" else "walkB%d" % k if h == "b" else "%s_walk%d" % (h, k)
            yield (name, 0, (nx - self.cx) * self.facing, ny - self.fy, 2)
        self.cx, self.fy = tx, ty                           # доходим точно, без «недоползания»

    # ---------- сидение ----------
    SIT_CHANCE = 0.45          # после остановки садится
    PAW_CHANCE = 0.30          # из позы «лапки внизу» поднимает лапку (иначе встаёт)
    PAW_EPISODES = [("sit_paw", 30), ("shuffle", 20), ("happy", 20), ("base", 25), ("sad", 5)]

    def pd_idle(self, lo, hi):
        """Сидит, лапки внизу: паузы, моргание, взмах хвостом (lo..hi тиков по 50 мс)."""
        total, limit = 0, random.randint(lo, hi)
        while total < limit:
            gap = random.randint(16, 36)
            total += gap
            yield ("pd0", 0, 0, 0, gap)
            for step in self.play(random.choice(["pd_blink", "pd_blink", "pd_tail"])):
                total += step[4]
                yield step

    def paw_episode(self):
        kind = random.choices([k for k, _ in self.PAW_EPISODES], [w for _, w in self.PAW_EPISODES])[0]
        if kind == "base":
            return self.play(random.choice(["base_blink", "base_tail", "base_wave"]))
        return self.play(kind)

    def paw_path(self):
        """Поднимает лапку, 1-3 случайных эпизода, опускает лапку."""
        yield from self.play("paw_up")
        for _ in range(random.randint(1, 3)):
            yield from self.paw_episode()
            yield ("b0", 0, 0, 0, random.randint(6, 16))
        yield from self.play("paw_down")

    SIT_MIN, SIT_MAX = 60, 1200   # одна посадка: от 3 секунд до 1 минуты (тики по 50 мс)

    def count(self, gen, attr):
        """Пропускает шаги дальше и считает их время (ходьба / сидение)."""
        for st in gen:
            setattr(self, attr, getattr(self, attr) + st[4])
            yield st

    def sit(self):
        """Садится (мордой туда, куда шёл), сидит с лапками внизу, иногда поднимает лапку, встаёт.
        Сидит столько, чтобы в сумме сидеть примерно столько же, сколько ходил (50 на 50)."""
        want = self.walked - self.seated
        want = int(min(self.SIT_MAX, max(self.SIT_MIN, want * random.uniform(0.8, 1.2))))
        start = self.seated
        fixed = sum(t for _, t in ANIMS["sit_down"]) + sum(t for _, t in ANIMS["stand_up"])
        if self.frame not in self.NEUTRAL:
            yield ("stand", 0, 0, 0, 1)
        yield from self.play("sit_down")
        if random.random() < self.PAW_CHANCE:
            rest = max(40, want - fixed)
            yield from self.pd_idle(int(rest * 0.4), int(rest * 0.5))
            yield from self.paw_path()
            left = want - fixed - (self.seated - start - sum(t for _, t in ANIMS["sit_down"]))
            yield from self.pd_idle(max(20, left - 10), max(20, left + 10))
        else:
            rest = max(40, want - fixed)
            yield from self.pd_idle(rest - 10, rest + 10)
        yield from self.play("stand_up")

    def get_up(self):
        """Встать из любой сидячей позы, не перескакивая кадры."""
        p, f = self.pose(), self.frame
        if p == "b":
            yield from self.play("paw_down")
        elif p == "pdd":
            for k in range(int(f[4:]), 7):
                yield ("pdd_%d" % k, 0, 0, 0, 1)
            yield ("pd0", 0, 0, 0, 2)
        if p == "sd":                                       # не досела - встаёт с того же кадра
            cur = int(f[3:])
            for k in reversed(SD_KEEP):
                if k <= cur:
                    yield ("sd_%d" % k, 0, 0, 0, 1)
            yield ("stand", 0, 0, 0, 2)
        else:
            yield from self.play("stand_up")

    def music(self):
        """Сменилась песня: садится, надевает наушники, слушает, встаёт."""
        self.in_music = True
        try:
            p, f = self.pose(), self.frame
            if p == "stand":
                if f not in self.NEUTRAL:
                    yield ("stand", 0, 0, 0, 1)
                yield from self.play("sit_down")
                yield ("pd0", 0, 0, 0, 8)
                p = "pd"
            elif p == "sd":                                 # досаживается
                cur = int(f[3:])
                for k in SD_KEEP:
                    if k >= cur:
                        yield ("sd_%d" % k, 0, 0, 0, 1)
                yield ("pd0", 0, 0, 0, 8)
                p = "pd"
            if p == "pd":
                yield from self.play("paw_up")
            elif p == "pdd":
                for k in range(int(f[4:]), -1, -1):
                    yield ("pdd_%d" % k, 0, 0, 0, 1)
                yield ("b0", 0, 0, 0, 4)
            yield from self.play("music")
            yield ("b0", 0, 0, 0, 8)
            yield from self.play("paw_down")
            yield ("pd0", 0, 0, 0, 12)
            yield from self.play("stand_up")
        finally:
            self.in_music = False

    # ---------- маршрут ----------
    def pick_target(self, d):
        """Точка впереди по ходу движения (d = 1 вправо, -1 влево); None, если до края зоны слишком близко."""
        x0, y0, x1, y1 = self.zone
        half = self.W // 2
        sx0, sy0, sx1, sy1 = self.screen
        lo, hi = max(x0, sx0 + half), min(x1, sx1 - half)
        room = (hi - self.cx) if d > 0 else (self.cx - lo)
        if room < 200:
            return None
        dist = random.uniform(min(400, room), min(room, 1200))
        return self.clamp(self.cx + d * dist, random.uniform(y0, y1))

    def routine(self):
        """Идёт -> останавливается -> иногда садится -> встаёт -> идёт ... Потом меняет сторону."""
        for _ in range(random.randint(1, 3)):
            target = self.pick_target(self.facing)
            if target is None:                              # упёрся в край зоны: меняем сторону
                self.facing = -self.facing
                target = self.pick_target(self.facing)
                if target is None:
                    break
            yield from self.count(self.walk_to(*target, glance=random.random() < self.GLANCE_CHANCE), "walked")
            for _ in range(random.randint(10, 30)):         # остановился, постоял 1-3 с
                yield ("blink", 0, 0, 0, 2) if random.random() < 0.08 else ("stand", 0, 0, 0, 2)
            if random.random() < self.SIT_CHANCE:
                yield from self.count(self.sit(), "seated")
        self.facing = -self.facing                          # смена стороны

    def idle(self):
        for _ in range(random.randint(6, 20)):
            yield ("blink", 0, 0, 0, 2) if random.random() < 0.12 else ("stand", 0, 0, 0, 2)

    def fall(self):
        h, v = self.dz, 4 * self.scale
        while h > 0:
            h = max(0, h - v)
            v += 2 * self.scale
            yield ("stretch", h, 0, 0, 1)
        yield ("crouch3", 0, 0, 0, 3)
        yield ("crouch1", 0, 0, 0, 2)

    def after_drop(self, landing=False):
        if self.dz > 0:
            yield from self.fall()
            yield ("stand", 0, 0, 0, 2)
        elif landing:                                       # кота поставили на пол: мягкое приземление
            yield ("crouch3", 0, 0, 0, 2)
            yield ("crouch1", 0, 0, 0, 2)
            yield ("stand", 0, 0, 0, 2)
        tx, ty = self.clamp(self.cx, self.fy)
        if abs(tx - self.cx) > 4 or abs(ty - self.fy) > 4:
            yield from self.walk_to(tx, ty)
        else:
            self.cx, self.fy = tx, ty

    def choose(self):
        if not self.in_zone(self.cx, self.fy):
            tx, ty = self.clamp(self.cx, self.fy)
            if abs(tx - self.cx) <= 8 and abs(ty - self.fy) <= 8:
                self.cx, self.fy = tx, ty              # совсем рядом: просто встаём на место
            else:
                return self.walk_to(tx, ty)
        gen = self.routine()
        return self.chain(self.get_up(), gen) if self.is_sitting() else gen

    # ---------- перетаскивание ----------
    def begin_drag(self):
        self.dragging = True
        self.interrupt = False
        self.dz = 0
        self.hold = 0
        self.gen = iter(())

    def drag_to(self, cx, fy):
        self.cx, self.fy = cx, fy

    def end_drag(self):
        self.dragging = False
        y0 = self.zone[1]
        if self.fy < y0:                  # отпустили в воздухе - падает на «пол» зоны
            self.dz = y0 - self.fy
            self.fy = y0
        self.start(self.after_drop(landing=True))

    # ---------- один тик ----------
    def apply(self, step):
        name, dz, dx, dy, hold = step
        self.frame = name
        self.dz = dz
        nx, ny = self.cx + dx * self.facing, self.fy + dy
        if self.in_zone(self.cx, self.fy):
            nx, ny = self.clamp(nx, ny)   # внутри зоны кот из неё не выходит
        self.cx, self.fy = nx, ny
        self.hold = max(0, hold - 1)

    def tick(self):
        if self.dragging:
            self.frame, self.dz = "stretch", 0
        elif self.hold > 0:
            self.hold -= 1
        else:
            if self.interrupt and (self.frame in self.NEUTRAL or self.frame in ("pd0", "b0")):
                self.interrupt = False
                self.gen = self.music()                     # music() сам решает, садиться или уже сидит
                self.hold = 0
            try:
                step = next(self.gen)
            except StopIteration:
                self.gen = self.choose()
                try:
                    step = next(self.gen)
                except StopIteration:
                    self.gen = self.idle()                 # пустое действие: просто постоим и выберем другое
                    step = ("stand", 0, 0, 0, 2)
            self.apply(step)
        return self.view()

    def view(self):
        name = self.frame + ("R" if self.facing == 1 else "L")
        left = int(self.cx - self.W / 2)
        top = int(self.fy - self.dz - self.H)
        return name, left, top


def main():
    if already_running():
        return
    enable_dpi_awareness()

    root = tk.Tk()
    root.title("Котик")
    root.overrideredirect(True)
    root.attributes("-transparentcolor", KEY)
    root.config(bg=KEY)

    cache = OrderedDict()
    cur = {"scale": 3}

    def image(name):
        """Кадр с нужным увеличением (целым, пиксели остаются квадратными); кэш ограничен."""
        key = (cur["scale"], name)
        im = cache.get(key)
        if im is None:
            im = tk.PhotoImage(data=FRAMES[name])
            if cur["scale"] > 1:
                im = im.zoom(cur["scale"])
            cache[key] = im
            if len(cache) > 160:
                cache.popitem(last=False)
        else:
            cache.move_to_end(key)
        return im

    cfg = load_config()
    scale = cfg.get("scale") if cfg.get("scale") in [k for k, _ in SCALES] else 3
    cur["scale"] = scale
    W, H = image("standR").width(), image("standR").height()

    def monitors():
        mons = get_monitors()
        if not mons:                                   # запасной вариант: один экран по данным Tk
            sw, sh = root.winfo_screenwidth(), root.winfo_screenheight()
            mons = [{"rect": (0, 0, sw, sh), "work": (0, 0, sw, sh - 50), "primary": True}]
        return mons

    def find_monitor(rect):
        for m in monitors():
            if rect and tuple(m["rect"]) == tuple(rect):
                return m
        return monitors()[0]

    mon = find_monitor(cfg.get("monitor"))
    cat = Cat(W, H, mon["rect"], mon["work"][3], scale, cfg.get("mode", "bottom"), cfg.get("rect"))

    label = tk.Label(root, bd=0, highlightthickness=0, bg=KEY, image=image("standR"))
    label.image = image("standR")
    label.pack()

    ui = queue.Queue()                    # команды из трея (он живёт в другом потоке)
    state = {"visible": cfg.get("visible", True), "quit": False, "overlay": False, "tray": None,
             "layer": cfg.get("layer") if cfg.get("layer") in ("top", "bottom") else "top", "n": 0,
             "music_react": True, "music_ok": False}      # реакция на смену песни всегда включена
    drag = {"dx": 0, "dy": 0}
    shown = {"name": None, "pos": None}

    def save_all():
        save_config({"mode": cat.mode, "rect": list(cat.custom_rect) if cat.custom_rect else None,
                     "monitor": list(cat.screen), "scale": cat.scale, "layer": state["layer"],
                     "visible": state["visible"]})

    def apply_layer():
        if state["layer"] == "top":
            root.attributes("-topmost", True)
        else:
            root.attributes("-topmost", False)
            push_to_bottom(root)

    def apply_scale(k):
        nonlocal W, H
        cur["scale"] = k
        cache.clear()
        W, H = image("standR").width(), image("standR").height()
        cat.set_scale(k, W, H)
        shown["name"] = None
        shown["pos"] = None

    # ---------- выбор зоны ----------
    def pick_zone():
        state["overlay"] = True
        sx0, sy0, sx1, sy1 = cat.screen
        sw, sh = sx1 - sx0, sy1 - sy0
        top = tk.Toplevel(root)
        top.overrideredirect(True)
        top.attributes("-topmost", True)
        top.attributes("-alpha", 0.35)
        top.geometry(f"{sw}x{sh}+{sx0}+{sy0}")
        top.config(bg="black", cursor="crosshair")
        canvas = tk.Canvas(top, bg="black", highlightthickness=0)
        canvas.pack(fill="both", expand=True)
        canvas.create_text(sw // 2, 70, fill="white", font=("Segoe UI", 20),
                           text="Выделите мышью зону, где будут ступать лапы котика.\n"
                                "Esc или правая кнопка - отмена")
        box = {"start": None, "rect": None}

        def close(rect=None):
            top.destroy()
            state["overlay"] = False
            if rect:
                cat.set_zone("custom", rect)
                cat.reposition()
                save_all()

        def press(e):
            box["start"] = (e.x, e.y)

        def move(e):
            if box["start"] is None:
                return
            if box["rect"] is not None:
                canvas.delete(box["rect"])
            x0, y0 = box["start"]
            box["rect"] = canvas.create_rectangle(x0, y0, e.x, e.y, outline="#39ff14", width=3)

        def release(e):
            if box["start"] is None:
                return
            x0, y0 = box["start"]
            x1, y1 = e.x, e.y
            if abs(x1 - x0) >= 80:
                close((sx0 + min(x0, x1), sy0 + min(y0, y1), sx0 + max(x0, x1), sy0 + max(y0, y1)))
            else:
                close()

        canvas.bind("<ButtonPress-1>", press)
        canvas.bind("<B1-Motion>", move)
        canvas.bind("<ButtonRelease-1>", release)
        canvas.bind("<Button-3>", lambda e: close())
        top.bind("<Escape>", lambda e: close())
        top.focus_force()

    # ---------- иконка в трее ----------
    def start_tray():
        if pystray is None:
            return None
        image = Image.open(io.BytesIO(base64.b64decode(ICON))).convert("RGBA")

        def toggle(icon=None, item=None):
            ui.put(("visible",))

        def put(*cmd):
            return lambda icon=None, item=None: ui.put(cmd)

        def is_scale(kk):
            return lambda item: cat.scale == kk

        def is_screen(rr):
            return lambda item: tuple(cat.screen) == rr

        def size_items():
            for k, title in SCALES:
                yield pystray.MenuItem(title, put("scale", k), checked=is_scale(k), radio=True)

        def screen_items():
            mons = monitors()
            for i, m in enumerate(mons):
                r = m["rect"]
                title = "Экран %d%s, %d×%d" % (i + 1, " (основной)" if m["primary"] else "",
                                               r[2] - r[0], r[3] - r[1])
                yield pystray.MenuItem(title, put("monitor", tuple(r)), checked=is_screen(tuple(r)), radio=True)

        menu = pystray.Menu(
            pystray.MenuItem("Показывать котика", toggle, checked=lambda item: state["visible"], default=True),
            pystray.MenuItem("Размер", pystray.Menu(size_items)),
            pystray.MenuItem("Экран", pystray.Menu(screen_items)),
            pystray.MenuItem("Зона прогулок", pystray.Menu(
                pystray.MenuItem("Выбрать зону на экране...", put("pick")),
                pystray.MenuItem("Моя зона", put("mode", "custom"),
                                 checked=lambda item: cat.mode == "custom", radio=True,
                                 enabled=lambda item: cat.custom_ok()),
                pystray.MenuItem("По низу экрана", put("mode", "bottom"),
                                 checked=lambda item: cat.mode == "bottom", radio=True),
                pystray.MenuItem("По всему экрану", put("mode", "screen"),
                                 checked=lambda item: cat.mode == "screen", radio=True),
            )),
            pystray.MenuItem("Положение", pystray.Menu(
                pystray.MenuItem("Поверх всех окон", put("layer", "top"),
                                 checked=lambda item: state["layer"] == "top", radio=True),
                pystray.MenuItem("Под окнами", put("layer", "bottom"),
                                 checked=lambda item: state["layer"] == "bottom", radio=True),
            )),
            pystray.MenuItem("Запускать вместе с Windows", put("autostart"),
                             checked=lambda item: autostart_enabled(),
                             enabled=lambda item: autostart_available()),
            pystray.MenuItem("Выход", put("quit")),
        )
        tray = pystray.Icon("CatPet", image, "Котик", menu)
        tray.run_detached()
        return tray

    def refresh_menu():
        """Меню в трее Windows строится заранее: после каждой команды перестраиваем его,
        иначе галочки (размер, экран, зона...) показывают предыдущее состояние."""
        if state["tray"] is not None:
            try:
                state["tray"].update_menu()
            except Exception:
                pass

    def finish():
        if state["tray"] is not None:
            state["tray"].stop()
        root.destroy()

    # ---------- главный цикл ----------
    def handle(cmd):
        kind = cmd[0]
        if kind == "quit":
            state["quit"] = True
        elif kind == "visible":
            state["visible"] = not state["visible"]
            save_all()
        elif kind == "pick" and not state["overlay"]:
            pick_zone()
        elif kind == "mode":
            cat.set_zone(cmd[1])
            cat.reposition()
            save_all()
        elif kind == "scale":
            apply_scale(cmd[1])
            save_all()
        elif kind == "monitor":
            m = find_monitor(cmd[1])
            cat.set_screen(m["rect"], m["work"][3])             # зона сбрасывается на «по низу»
            shown["pos"] = None
            save_all()
        elif kind == "layer":
            state["layer"] = cmd[1]
            apply_layer()
            save_all()
        elif kind == "autostart":
            set_autostart(not autostart_enabled())
        elif kind == "music":
            if state["visible"]:
                cat.request("music")

    def loop():
        while True:
            try:
                cmd = ui.get_nowait()
            except queue.Empty:
                break
            handle(cmd)
            refresh_menu()
        if state["quit"]:
            finish()
            return
        if state["overlay"]:
            root.after(TICK, loop)
            return
        if not state["visible"]:
            if root.winfo_viewable():
                root.withdraw()
            root.after(200, loop)
            return
        if not root.winfo_viewable():
            root.deiconify()
            apply_layer()
        state["n"] += 1
        if state["layer"] == "bottom" and state["n"] % 20 == 0:
            push_to_bottom(root)                  # клик по коту поднимает окно - опускаем обратно
        name, left, top = cat.tick()
        if name != shown["name"]:
            im = image(name)
            label.config(image=im)
            label.image = im                              # чтобы кадр не удалился, пока показан
            shown["name"] = name
        if (left, top) != shown["pos"]:
            root.geometry(f"+{left}+{top}")
            shown["pos"] = (left, top)
        root.after(TICK, loop)

    # ---------- мышь ----------
    def start_drag(event):
        drag["dx"], drag["dy"] = event.x, event.y
        cat.begin_drag()

    def do_drag(event):
        left = root.winfo_pointerx() - drag["dx"]
        top = root.winfo_pointery() - drag["dy"]
        cat.drag_to(left + W / 2, top + H)

    def monitor_at(x, y):
        """Экран, на котором лежит точка (или ближайший к ней)."""
        best, best_d = None, None
        for m in monitors():
            x0, y0, x1, y1 = m["rect"]
            dx = max(x0 - x, 0, x - x1)
            dy = max(y0 - y, 0, y - y1)
            d = dx * dx + dy * dy
            if best is None or d < best_d:
                best, best_d = m, d
        return best

    def stop_drag(event):
        m = monitor_at(cat.cx, cat.fy - H / 2)
        if m is not None and tuple(m["rect"]) != tuple(cat.screen):
            cat.move_to_screen(m["rect"], m["work"][3])      # перенесли на другой экран: экран и зона «по низу»
            save_all()
            refresh_menu()
        cat.end_drag()

    context = tk.Menu(root, tearoff=0)
    context.add_command(label="Спрятать котика (вернуть - из трея)", command=lambda: ui.put(("visible",)))
    context.add_separator()
    context.add_command(label="Выход", command=lambda: ui.put(("quit",)))

    label.bind("<Button-1>", start_drag)
    label.bind("<B1-Motion>", do_drag)
    label.bind("<ButtonRelease-1>", stop_drag)
    label.bind("<Button-3>", lambda e: context.tk_popup(e.x_root, e.y_root))

    apply_layer()
    state["music_ok"] = start_media_watch(lambda: ui.put(("music",)), lambda: state["music_react"])
    state["tray"] = start_tray()
    loop()
    root.mainloop()


if __name__ == "__main__":
    main()
